import numpy as np

def clamp(x, lo, hi):
    """Saturate x into [lo, hi], elementwise."""
    return np.clip(x, lo, hi)

import numpy as np

def count_upcrossings(x, level):
    """Count positions i with x[i] < level and x[i+1] >= level."""
    over = (np.asarray(x) >= level).astype(np.int64)
    return int(np.count_nonzero(np.diff(over) == 1))

import numpy as np

def moving_average(x, w):
    """Valid-window moving average via one cumulative sum."""
    x = np.asarray(x, dtype=np.float64)
    c = np.concatenate(([0.0], np.cumsum(x)))
    return np.round((c[w:] - c[:-w]) / w, 4)
